/**
 * Tests for the workflow expression evaluator (port of the ``TestExpressions``
 * class in upstream ``tests/test_workflows.py`` and of
 * ``tests/unit/test_condition_expression_block.py``).
 *
 * The second half is a differential fixture generated by running the upstream
 * Python evaluator (spec-kit v1.2.5) over the same inputs; every case must
 * produce the identical value / error / validator message.
 */

import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { StepContext, pyEquals, pyStr } from '../src/workflows/base.js';
import {
  conditionHasMalformedExpressionBlock,
  conditionIsInterpolatedToText,
  conditionIsNeverEvaluated,
  evaluateCondition,
  evaluateExpression,
  formatConditionCorrection,
  formatConditionRemediation,
} from '../src/workflows/expressions.js';
import { DoWhileStep } from '../src/workflows/step/do-while.js';
import { IfThenStep } from '../src/workflows/step/if-then.js';
import { WhileStep } from '../src/workflows/step/while-loop.js';

const ctx = (init: ConstructorParameters<typeof StepContext>[0] = {}): StepContext => new StepContext(init);
const ev = (t: unknown, c: StepContext = ctx()): unknown => evaluateExpression(t, c);

describe('TestExpressions', () => {
  test('simple variable and step output reference', () => {
    expect(ev('{{ inputs.name }}', ctx({ inputs: { name: 'login' } }))).toBe('login');
    expect(ev('{{ steps.specify.output.file }}', ctx({ steps: { specify: { output: { file: 'spec.md' } } } }))).toBe(
      'spec.md',
    );
  });

  test('string interpolation', () => {
    expect(ev('Feature: {{ inputs.name }} done', ctx({ inputs: { name: 'login' } }))).toBe('Feature: login done');
  });

  test('multi expression without surrounding text (#3208)', () => {
    expect(ev('{{ context.run_id }} {{ inputs.issue }}', ctx({ inputs: { issue: '23' }, runId: '47c5eb4b' }))).toBe(
      '47c5eb4b 23',
    );
    expect(ev('{{ inputs.a }}{{ inputs.b }}', ctx({ inputs: { a: 'foo', b: 'bar' } }))).toBe('foobar');
  });

  test('single expression with literal braces keeps its type', () => {
    expect(ev("{{ inputs.text | contains('{{') }}", ctx({ inputs: { text: 'uses {{ jinja }} syntax' } }))).toBe(true);
    expect(ev("{{ inputs.text | contains('}}') }}", ctx({ inputs: { text: 'uses }} syntax' } }))).toBe(true);
  });

  test('multi expression with literal braces in arguments', () => {
    const c = ctx({ inputs: { name: 'Bob', missing: null } });
    expect(ev("{{ inputs.name }}: {{ inputs.missing | default('}}') }}", c)).toBe('Bob: }}');
    expect(ev("{{ inputs.missing | default('}}') }} / {{ inputs.name }}", c)).toBe('}} / Bob');
    expect(ev("{{ inputs.name }} {{ inputs.missing | default('{{') }}", c)).toBe('Bob {{');
  });

  test('unbalanced quote in a multi-expression template still raises', () => {
    const c = ctx({ inputs: { name: 'Bob', missing: null } });
    expect(() => ev("{{ inputs.name }} {{ inputs.missing | default('oops }}", c)).toThrow();
  });

  test('comparisons', () => {
    const c = ctx({ inputs: { scope: 'full' } });
    expect(ev("{{ inputs.scope == 'full' }}", c)).toBe(true);
    expect(ev("{{ inputs.scope == 'partial' }}", c)).toBe(false);
    expect(ev('{{ steps.run-tests.output.exit_code != 0 }}', ctx({ steps: { 'run-tests': { output: { exit_code: 1 } } } }))).toBe(true);
    const p = ctx({ steps: { plan: { output: { task_count: 7 } } } });
    expect(ev('{{ steps.plan.output.task_count > 5 }}', p)).toBe(true);
    expect(ev('{{ steps.plan.output.task_count < 5 }}', p)).toBe(false);
  });

  test('ordering comparison of non-numeric strings', () => {
    expect(ev("{{ inputs.d < '2026-02-01' }}", ctx({ inputs: { d: '2026-01-01' } }))).toBe(true);
    expect(ev("{{ inputs.d > '2026-02-01' }}", ctx({ inputs: { d: '2026-01-01' } }))).toBe(false);
    expect(ev("{{ inputs.name > 'alpha' }}", ctx({ inputs: { name: 'beta' } }))).toBe(true);
    expect(ev("{{ inputs.v > '9' }}", ctx({ inputs: { v: '10' } }))).toBe(true);
    expect(ev("{{ inputs.n > 'abc' }}", ctx({ inputs: { n: 5 } }))).toBe(false);
  });

  test('boolean and / or', () => {
    expect(ev('{{ inputs.a and inputs.b }}', ctx({ inputs: { a: true, b: true } }))).toBe(true);
    expect(ev('{{ inputs.a or inputs.b }}', ctx({ inputs: { a: false, b: true } }))).toBe(true);
  });

  test('list literals', () => {
    expect(ev('{{ ["a, b", "c"] }}')).toEqual(['a, b', 'c']);
    expect(ev("{{ ['p, q, r'] }}")).toEqual(['p, q, r']);
    expect(ev('{{ [1, 2, 3] }}')).toEqual([1, 2, 3]);
    expect(ev('{{ [] }}')).toEqual([]);
    expect(ev('{{ [["a", "b"], "c"] }}')).toEqual([['a', 'b'], 'c']);
    expect(ev('{{ [1, 2,] }}')).toEqual([1, 2]);
    expect(ev('{{ [1,, 2] }}')).toEqual([1, 2]);
    expect(ev("{{ ['', 'a'] }}")).toEqual(['', 'a']);
  });

  test('list literal followed by an index is not misparsed', () => {
    expect(ev('{{ [1,2,3][1] }}')).toBeNull();
    expect(ev('{{ [1,2][0] }}')).toBeNull();
    expect(ev('{{ [[1, 2], 3] }}')).toEqual([[1, 2], 3]);
    expect(ev("{{ ['a]', 'b'] }}")).toEqual(['a]', 'b']);
  });

  test('operator splitting is quote aware', () => {
    const c = ctx({ inputs: { mode: 'read and write' } });
    expect(ev("{{ inputs.mode == 'read and write' }}", c)).toBe(true);
    expect(ev("{{ inputs.mode == 'read or write' }}", c)).toBe(false);
    expect(ev("{{ 'approve or reject' == inputs.x }}", ctx({ inputs: { x: 'approve or reject' } }))).toBe(true);
    expect(ev("{{ 'cat' in 'cat and dog' }}")).toBe(true);
    expect(evaluateCondition("{{ 'done' == 'failed' }}", ctx())).toBe(false);
    expect(evaluateCondition("{{ 'done' == 'done' }}", ctx())).toBe(true);
    expect(ev("{{ 'a == b' }}")).toBe('a == b');
    const plain = ctx({ inputs: { a: 1, b: 2, mode: 'read' } });
    expect(ev('{{ inputs.a == 1 and inputs.b == 2 }}', plain)).toBe(true);
    expect(ev('{{ inputs.a == 9 or inputs.b == 2 }}', plain)).toBe(true);
    expect(ev("{{ inputs.missing | default('a and b') }}", plain)).toBe('a and b');
  });

  test('pipe detection is quote aware', () => {
    expect(ev("{{ inputs.x == 'a|b' }}", ctx({ inputs: { x: 'a|b' } }))).toBe(true);
    expect(ev("{{ 'a|b' in inputs.s }}", ctx({ inputs: { s: 'x a|b y' } }))).toBe(true);
    expect(ev("{{ 'a|b|c' }}")).toBe('a|b|c');
    const c2 = ctx({ inputs: { items: ['a', 'b'], s: 'xabz' } });
    expect(ev('{{ inputs.items | join("-") }}', c2)).toBe('a-b');
    expect(ev("{{ inputs.missing | default('a|b') }}", c2)).toBe('a|b');
    expect(ev("{{ inputs.tags | join(' | ') }}", ctx({ inputs: { tags: ['a|b', 'c'] } }))).toBe('a|b | c');
  });

  test('membership against non-iterables is false, not an error', () => {
    const c = ctx({ inputs: { tag: 'x', count: 5, ratio: 1.5, flag: true } });
    for (const right of ['count', 'ratio', 'flag', 'missing']) {
      expect(ev(`{{ inputs.tag in inputs.${right} }}`, c)).toBe(false);
      expect(ev(`{{ inputs.tag not in inputs.${right} }}`, c)).toBe(true);
    }
    const ok = ctx({ inputs: { items: ['x', 'y'], s: 'xyz' } });
    expect(ev("{{ 'x' in inputs.items }}", ok)).toBe(true);
    expect(ev("{{ 'z' not in inputs.items }}", ok)).toBe(true);
    expect(ev("{{ 'y' in inputs.s }}", ok)).toBe(true);
  });

  test('registered filters', () => {
    const c = ctx({
      inputs: { tags: ['a', 'b', 'c'], text: 'hello world', missing: '', rows: [{ id: 'a' }, { id: 'b' }] },
      steps: { emit: { output: { stdout: '{"n": 1}' } } },
    });
    expect(ev("{{ inputs.missing | default('fb') }}", c)).toBe('fb');
    expect(ev("{{ inputs.tags | join(', ') }}", c)).toBe('a, b, c');
    expect(ev("{{ inputs.rows | map('id') }}", c)).toEqual(['a', 'b']);
    expect(ev("{{ inputs.text | contains('world') }}", c)).toBe(true);
    expect(ev('{{ steps.emit.output.stdout | from_json }}', c)).toEqual({ n: 1 });
  });

  test('filter errors', () => {
    const c = ctx({ inputs: { items: [1, 2, 3], tags: ['a', 'b'], text: 'hello', rows: [{ id: 'a' }] } });
    expect(() => ev('{{ inputs.items | bogus }}', c)).toThrow("unknown filter 'bogus'");
    expect(() => ev("{{ inputs.text | upper('x') }}", c)).toThrow("upper: expected '| upper' with no arguments");
    expect(() => ev('{{ inputs.rows | map(5) }}', c)).toThrow('map: expected a string attribute name');
    expect(() => ev('{{ inputs.tags | join(5) }}', c)).toThrow('join: expected a string separator');
    expect(() => ev('{{ inputs.text | contains(5) }}', c)).toThrow('contains: expected a string argument');
    expect(() => ev('{{ inputs.tags | join }}', c)).toThrow("filter 'join' used in an unsupported form");
    expect(() => ev('{{ inputs.tags | map }}', c)).toThrow("filter 'map' used in an unsupported form");
    expect(() => ev("{{ inputs.missing | default('7') > '5' }}", c)).toThrow('unsupported form');
    expect(() => ev("{{ inputs.tags | join(',') extra }}", c)).toThrow('unsupported form');
    expect(() => ev('{{ inputs.missing | default(1, 2) }}', c)).toThrow('unsupported form');
    expect(() => ev('{{ inputs.missing | default([1,2], 3) }}', c)).toThrow('unsupported form');
    expect(() => ev("{{ inputs.rows | map('id') | bogus }}", c)).toThrow("unknown filter 'bogus'");
  });

  test('from_json strictness', () => {
    const c = ctx({ steps: { emit: { output: { stdout: '{"a": 1}', bad: 'not json', code: 0 } } } });
    expect(() => ev('{{ steps.emit.output.bad | from_json }}', c)).toThrow('from_json: invalid JSON');
    expect(() => ev('{{ steps.emit.output.code | from_json }}', c)).toThrow('expected a JSON string');
    for (const bad of ['from_json()', "from_json('x')", 'from_json ()', 'from_json)', 'from_json extra', "from_json 'x'"]) {
      expect(() => ev('{{ steps.emit.output.stdout | ' + bad + ' }}', c)).toThrow('from_json: expected');
    }
  });

  test('single argument containing a comma still works', () => {
    const c = ctx({ inputs: { tags: ['a', 'b'] } });
    expect(ev('{{ inputs.tags | join(", ") }}', c)).toBe('a, b');
    expect(ev('{{ inputs.missing | default("a, b") }}', c)).toBe('a, b');
    expect(ev('{{ inputs.missing | default([1, 2]) }}', c)).toEqual([1, 2]);
    expect(ev('{{ inputs.missing | default([]) }}', c)).toEqual([]);
  });

  test('filters mixed with an operator are refused as ambiguous', () => {
    const c = ctx({ inputs: { count: 10, name: 'x', value: 0, flag: true } });
    expect(() => ev('{{ inputs.count > inputs.limit | default(5) }}', c)).toThrow('ambiguous filter precedence');
    expect(() => ev('{{ inputs.name == inputs.other | default("x") }}', c)).toThrow('ambiguous filter precedence');
    expect(() => ev('{{ inputs.a and inputs.b | default(1) }}', c)).toThrow('ambiguous filter precedence');
    expect(() => ev('{{ not inputs.missing | default(1) }}', c)).toThrow('ambiguous filter precedence');
    expect(() => ev('{{ inputs.flag and not inputs.value | default(1) }}', c)).toThrow('ambiguous filter precedence');
    expect(ev('{{ not inputs.value }}', c)).toBe(true);
    expect(ev('{{ not inputs.flag }}', c)).toBe(false);
  });

  test('chained filters apply left to right', () => {
    const c = ctx({ inputs: { rows: [{ name: 'a' }, { name: 'b' }], missing: null } });
    expect(ev("{{ inputs.rows | map('name') | join(', ') }}", c)).toBe('a, b');
    expect(ev("{{ inputs.rows | map('name') | join(', ') | contains('a') }}", c)).toBe(true);
    expect(ev("{{ inputs.missing | default('x') | contains('x') }}", c)).toBe(true);
  });

  test('condition evaluation strips captured output', () => {
    expect(evaluateCondition('{{ inputs.ready }}', ctx({ inputs: { ready: true } }))).toBe(true);
    expect(evaluateCondition('{{ inputs.missing }}', ctx())).toBe(false);
    expect(evaluateCondition('{{ steps.check.output.stdout }}', ctx({ steps: { check: { output: { stdout: 'false\n' } } } }))).toBe(false);
    for (const raw of ['false\n', 'false\r\n', ' false', 'false ', 'FALSE\n']) expect(evaluateCondition(raw, ctx())).toBe(false);
    for (const raw of ['true\n', ' true ', 'TRUE\r\n']) expect(evaluateCondition(raw, ctx())).toBe(true);
    expect(evaluateCondition('   ', ctx())).toBe(true);
    expect(evaluateCondition('falsey', ctx())).toBe(true);
    expect(evaluateCondition('', ctx())).toBe(false);
  });

  test('literals, passthrough, indexing and context', () => {
    expect(ev(42)).toBe(42);
    expect(ev(null)).toBeNull();
    expect(ev("{{ 'hello' }}")).toBe('hello');
    expect(ev('{{ 42 }}')).toBe(42);
    expect(ev('{{ true }}')).toBe(true);
    expect(ev('{{ false }}')).toBe(false);
    const c = ctx({ steps: { tasks: { output: { task_list: [{ file: 'a.md' }, { file: 'b.md' }] } } } });
    expect(ev('{{ steps.tasks.output.task_list[0].file }}', c)).toBe('a.md');
    expect(ev('{{ context.run_id }}', ctx({ runId: 'a1b2c3d4' }))).toBe('a1b2c3d4');
    expect(ev('{{ context.run_id }}', ctx())).toBe('');
    expect(ev('RUN_ID={{ context.run_id }}', ctx({ runId: 'deadbeef' }))).toBe('RUN_ID=deadbeef');
    expect(ev('{{ context.workflow_dir }}', ctx({ workflowDir: '/tmp/wf' }))).toBe('/tmp/wf');
  });

  test('interpolation renders values like Python str()', () => {
    const c = ctx({ inputs: { flag: true, none: null, list: ['a', 1], obj: { k: "v'" } } });
    expect(ev('{{ inputs.flag }}|{{ inputs.none }}|{{ inputs.list }}|{{ inputs.obj }}', c)).toBe(
      `True||['a', 1]|{'k': "v'"}`,
    );
  });
});

describe('condition validation helpers', () => {
  test('brace-less conditions are always true at runtime and flagged by every loop/branch step', () => {
    const c = ctx({ inputs: { count: 0 } });
    expect(evaluateCondition('{{ inputs.count > 100 }}', c)).toBe(false);
    expect(evaluateCondition('inputs.count > 100', c)).toBe(true);
    for (const Cls of [IfThenStep, WhileStep, DoWhileStep]) {
      const errors = new Cls().validate({ id: 's', condition: 'inputs.count > 100', then: [], steps: [] });
      expect(errors.length).toBe(1);
      expect(errors[0]).toContain('inputs.count > 100');
      expect(errors[0]).toContain('"{{ inputs.count > 100 }}"');
    }
  });

  test('never-evaluated classification', () => {
    expect(conditionIsNeverEvaluated('')).toBe(false);
    expect(conditionIsNeverEvaluated('   ')).toBe(true);
    expect(conditionIsNeverEvaluated('true')).toBe(false);
    expect(conditionIsNeverEvaluated(' FALSE ')).toBe(false);
    expect(conditionIsNeverEvaluated(true)).toBe(false);
    expect(conditionIsNeverEvaluated('{{ inputs.x }}')).toBe(false);
    expect(conditionIsNeverEvaluated('{{ inputs.x')).toBe(true);
    expect(conditionHasMalformedExpressionBlock("{{ inputs.missing | default('oops }}")).toBe(true);
    expect(conditionIsInterpolatedToText('{{ inputs.a }} and {{ inputs.b }}')).toBe(true);
    expect(conditionIsInterpolatedToText('{{ inputs.a and inputs.b }}')).toBe(false);
  });

  test('corrections are YAML-safe and keep non-ASCII readable', () => {
    expect(formatConditionCorrection('inputs.name == "zzz"')).toBe('"{{ inputs.name == \\"zzz\\" }}"');
    expect(formatConditionCorrection('{{ inputs.count > 100')).toBe('"{{ inputs.count > 100 }}"');
    expect(formatConditionCorrection("inputs.name == 'mười'")).toContain('mười');
    expect(formatConditionCorrection("inputs.x == '}}'")).toBe('"{{ inputs.x == \'}}\' }}"');
    expect(formatConditionCorrection('   ')).toBe('"{{ }}"');
  });

  test('remediation withholds corrections that would invert the condition', () => {
    expect(formatConditionRemediation('inputs.count > 100')).toBe('Wrap the expression: "{{ inputs.count > 100 }}".');
    expect(formatConditionRemediation('   ')).toContain('there is no expression here to wrap');
    expect(formatConditionRemediation("{{ inputs.name == 'abc")).toContain('the quote opened in it is never closed');
    expect(formatConditionRemediation('inputs.name ==')).toContain('an operator in it is missing an operand');
    expect(formatConditionRemediation('inputs.f(]')).toContain('its brackets do not balance');
    expect(formatConditionRemediation("bogus == 'x'")).toContain("'bogus' is not one of the namespace roots");
    expect(formatConditionRemediation('inputs.items | bogus')).toContain(
      "the evaluator rejects it (unknown filter 'bogus')",
    );
    expect(formatConditionRemediation('steps.emit.output.stdout | from_json')).toStartWith('Wrap the expression');
  });
});

// ============================================================================
// Differential fixture (tests/fixtures/workflows/expressions.json, generated
// from upstream Python spec-kit v1.2.5 by
// tests/fixtures/generate/workflow_expressions.py)
// ============================================================================

const FIXTURE = JSON.parse(
  readFileSync(join(import.meta.dir, 'fixtures', 'workflows', 'expressions.json'), 'utf-8'),
) as { conds: unknown[]; templates: unknown[]; ctx: { inputs: unknown; steps: unknown } };

type TemplateCase = { t: string; v?: unknown; s?: string | null; err?: string };
type CondCase = {
  c: string;
  condition_is_never_evaluated: boolean;
  condition_is_interpolated_to_text: boolean;
  condition_has_malformed_expression_block: boolean;
  format_condition_remediation: string;
  format_condition_correction: string;
  eval: boolean | string;
  validate: Record<string, string[]>;
};

describe('differential fixture: evaluateExpression', () => {
  const c = new StepContext({
    inputs: FIXTURE.ctx.inputs as unknown as Record<string, unknown>,
    steps: FIXTURE.ctx.steps as unknown as Record<string, Record<string, unknown>>,
    runId: 'r1',
  });
  for (const tc of FIXTURE.templates as unknown as TemplateCase[]) {
    test(`template ${JSON.stringify(tc.t)}`, () => {
      if (tc.err !== undefined) {
        let caught: Error | null = null;
        try {
          evaluateExpression(tc.t, c);
        } catch (e) {
          caught = e as Error;
        }
        expect(caught).not.toBeNull();
        const [pyType, ...rest] = tc.err.split(': ');
        expect((caught as Error).name).toBe(pyType as string);
        if (!tc.err.includes('invalid JSON')) expect((caught as Error).message).toBe(rest.join(': '));
        return;
      }
      const v = evaluateExpression(tc.t, c);
      expect(pyEquals(v, tc.v)).toBe(true);
      if (tc.s !== null && tc.s !== undefined) expect(pyStr(v)).toBe(tc.s);
      else expect(typeof v).toBe('string');
    });
  }
});

describe('differential fixture: condition helpers and step validators', () => {
  const c = new StepContext({ inputs: { count: 0, ready: false, name: 'abc', tags: ['a'] } });
  const classes: Record<string, typeof IfThenStep | typeof WhileStep | typeof DoWhileStep> = {
    If: IfThenStep,
    While: WhileStep,
    'Do-while': DoWhileStep,
  };
  for (const cc of FIXTURE.conds as unknown as CondCase[]) {
    test(`condition ${JSON.stringify(cc.c)}`, () => {
      expect(conditionIsNeverEvaluated(cc.c)).toBe(cc.condition_is_never_evaluated);
      expect(conditionIsInterpolatedToText(cc.c)).toBe(cc.condition_is_interpolated_to_text);
      expect(conditionHasMalformedExpressionBlock(cc.c)).toBe(cc.condition_has_malformed_expression_block);
      expect(formatConditionRemediation(cc.c)).toBe(cc.format_condition_remediation);
      expect(formatConditionCorrection(cc.c)).toBe(cc.format_condition_correction);
      let evResult: boolean | string;
      try {
        evResult = evaluateCondition(cc.c, c);
      } catch (e) {
        evResult = 'ERR ' + (e as Error).name;
      }
      expect(evResult).toBe(cc.eval);
      for (const [label, Cls] of Object.entries(classes)) {
        expect(new Cls().validate({ id: 's', condition: cc.c, then: [], steps: [] })).toEqual(cc.validate[label] as string[]);
      }
    });
  }
});
